        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos_from(value, default=(0, 0)):
        try:
            if isinstance(value, (list, tuple)) and len(value) >= 2:
                return int(value[0]), int(value[1])
        except:
            pass
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def best_by_distance(items, src, reverse=False):
        best_item = None
        best_score = None
        for item in items:
            p = pos_from(item, None)
            if p is None:
                continue
            score = manhattan(src, p)
            if best_item is None or (score > best_score if reverse else score < best_score):
                best_item = p
                best_score = score
        return best_item

